/**
 * EblanEng (Eblan Engine) - High-Performance WebAssembly Voxel Core
 * Rust-powered procedural generation, greedy meshing & multi-threaded Web Workers
 */

(function(window) {
    'use strict';

    const WASM_BASE64 = '';
    const WORKER_BASE64 = '';

    class EblanEngine {
        constructor() {
            this.wasmInstance = null;
            this.wasmMemory = null;
            this.exports = null;
            this.ready = false;
            this.currentSeed = null;
            this.materialList = [];
            this.materialMap = new Map();
            this.syncedBlockMaterials = [];
            this.initPromise = null;
            this.worker = null;
            this.workerReady = false;
            this.pendingTasks = new Map();
            this.taskIdCounter = 1;
        }

        async init(seed = 1337) {
            this.currentSeed = seed;
            if (this.initPromise) {
                await this.initPromise;
                this.setSeed(seed);
                return true;
            }

            this.initPromise = (async () => {
                try {
                    let wasmBytes = null;
                    if (typeof window !== 'undefined' && window.location && window.location.protocol !== 'file:') {
                        try {
                            const response = await fetch('js/eblan_core.wasm');
                            if (response.ok) {
                                wasmBytes = await response.arrayBuffer();
                            }
                        } catch (e) {}
                    }

                    if (!wasmBytes) {
                        const binaryStr = atob(WASM_BASE64);
                        const len = binaryStr.length;
                        const bytes = new Uint8Array(len);
                        for (let i = 0; i < len; i++) {
                            bytes[i] = binaryStr.charCodeAt(i);
                        }
                        wasmBytes = bytes.buffer;
                    }

                    const result = await WebAssembly.instantiate(wasmBytes, {});

                    this.wasmInstance = result.instance;
                    this.exports = result.instance.exports;
                    this.wasmMemory = this.exports.memory;

                    const effectiveSeed = (this.currentSeed !== null) ? this.currentSeed : seed;
                    this.exports.eblan_init(effectiveSeed);
                    this.ready = true;

                    // Initialize Background Web Worker for multi-threaded chunk generation
                    this.initWorker(effectiveSeed);

                    console.log('⚡ [EblanEng] Rust WebAssembly Engine Core activated (WorldGen, Greedy Mesher & Multi-Threading).');
                    return true;
                } catch (err) {
                    console.warn('⚠️ [EblanEng] Failed to initialize WebAssembly core, falling back to JS:', err);
                    this.ready = false;
                    return false;
                }
            })();

            return this.initPromise;
        }

        setSeed(seed) {
            this.currentSeed = seed;
            if (this.ready && this.exports && this.exports.eblan_set_seed) {
                this.exports.eblan_set_seed(seed);
            }
            if (this.worker) {
                this.worker.postMessage({ type: 'SET_SEED', seed: seed });
            }
        }

        initWorker(seed) {
            try {
                if (typeof Worker === 'undefined') return;
                this.workerStartup = new Promise(resolve => { this.resolveWorkerStartup = resolve; });
                this.workerStartupTimer = setTimeout(() => this.failWorker(), 15000);

                let blob;
                try {
                    const workerSource = decodeURIComponent(escape(atob(WORKER_BASE64)));
                    blob = new Blob([workerSource], { type: 'application/javascript' });
                    const blobUrl = URL.createObjectURL(blob);
                    this.worker = new Worker(blobUrl);
                    URL.revokeObjectURL(blobUrl);
                } catch (e) {
                    // Fallback to direct script path
                    this.worker = new Worker('js/eblan_worker.js');
                }

                const activeWorker = this.worker;
                this.worker.onmessage = (e) => {
                    if (this.worker !== activeWorker) return;
                    const msg = e.data;
                    if (!msg) return;

                    if (msg.type === 'ERROR') { this.failWorker(); return; }
                    if (msg.type === 'READY') {
                        this.workerReady = true;
                        clearTimeout(this.workerStartupTimer);
                        this.resolveWorkerStartup?.();
                        console.log('🧵 [EblanEng] Background Worker Thread ready for multi-threaded chunk pipeline.');
                        if (this.currentSeed !== null) {
                            this.worker.postMessage({ type: 'SET_SEED', seed: this.currentSeed });
                        }
                        this.syncWorkerMaterials();
                        return;
                    }

                    if (msg.type === 'CHUNK_READY') {
                        const cb = this.pendingTasks.get(msg.id);
                        if (cb) {
                            this.pendingTasks.delete(msg.id);
                            clearTimeout(cb.timer);
                            cb.resolve(msg);
                        }
                    } else if (msg.type === 'CHUNK_FAILED') {
                        const cb = this.pendingTasks.get(msg.id);
                        if (cb) {
                            this.pendingTasks.delete(msg.id);
                            clearTimeout(cb.timer);
                            cb.reject(new Error(msg.error || 'Worker chunk failed'));
                        }
                    }
                };

                this.worker.onerror = () => this.failWorker();
                this.worker.onmessageerror = () => this.failWorker();
                this.worker.postMessage({ type: 'INIT', seed: seed, baseUrl: window.location.href });
            } catch (err) {
                this.failWorker();
                console.warn('⚠️ [EblanEng] Background Worker initialization skipped (using main-thread Wasm):', err);
            }
        }

        failWorker() {
            clearTimeout(this.workerStartupTimer);
            this.resolveWorkerStartup?.();
            this.workerReady = false;
            this.worker?.terminate();
            this.worker = null;
            for (const task of this.pendingTasks.values()) {
                clearTimeout(task.timer);
                task.reject(new Error('Chunk worker unavailable'));
            }
            this.pendingTasks.clear();
        }

        syncMaterials(textureManager) {
            if (!this.ready || !textureManager) return;
            this.materialList = [];
            this.materialMap.clear();

            const getMatId = (mat) => {
                if (!mat) return 0;
                if (this.materialMap.has(mat)) return this.materialMap.get(mat);
                const id = this.materialList.length;
                this.materialList.push(mat);
                this.materialMap.set(mat, id);
                return id;
            };

            const blockMaterials = [];

            for (let block = 0; block < 256; block++) {
                const blockMat = textureManager.getBlockMaterial(block);
                if (Array.isArray(blockMat)) {
                    for (let f = 0; f < 6; f++) {
                        const mId = getMatId(blockMat[f] || blockMat[0]);
                        this.exports.eblan_set_block_material(block, f, mId);
                        blockMaterials.push({ block, face: f, matId: mId });
                    }
                } else if (blockMat) {
                    const mId = getMatId(blockMat);
                    for (let f = 0; f < 6; f++) {
                        this.exports.eblan_set_block_material(block, f, mId);
                        blockMaterials.push({ block, face: f, matId: mId });
                    }
                }
            }

            this.syncedBlockMaterials = blockMaterials;
            this.syncWorkerMaterials();
        }

        syncWorkerMaterials() {
            if (this.worker && this.workerReady && this.syncedBlockMaterials) {
                this.worker.postMessage({
                    type: 'SYNC_MATERIALS',
                    blockMaterials: this.syncedBlockMaterials
                });
            }
        }

        noise2D(x, y) {
            if (this.ready) {
                return this.exports.eblan_noise2d(x, y);
            }
            return 0;
        }

        noise3D(x, y, z) {
            if (this.ready) {
                return this.exports.eblan_noise3d(x, y, z);
            }
            return 0;
        }

        fbm2D(x, y, octaves = 4, persistence = 0.5, lacunarity = 2.0) {
            if (this.ready) {
                return this.exports.eblan_fbm2d(x, y, octaves, persistence, lacunarity);
            }
            return 0;
        }

        // Rust Procedural Chunk Generator
        generateChunk(cx, cz, dimension = 0, worldType = 0, waterLevel = 6) {
            if (!this.ready) return null;
            this.exports.eblan_generate_chunk(cx, cz, dimension, worldType, waterLevel);
            const ptr = this.exports.eblan_get_chunk_voxels_ptr();
            const vox = new Uint8Array(8192);
            vox.set(new Uint8Array(this.wasmMemory.buffer, ptr, 8192));
            return vox;
        }

        // Asynchronous Worker Chunk Generation & Meshing
        requestChunkAsync(options) {
            if (!this.worker || !this.workerReady) return null;

            const taskId = this.taskIdCounter++;
            return new Promise((resolve, reject) => {
                const timer = setTimeout(() => this.failWorker(), 15000);
                this.pendingTasks.set(taskId, { resolve, reject, timer });
                try { this.worker.postMessage({
                    type: 'GEN_AND_MESH',
                    id: taskId,
                    cx: options.cx,
                    cz: options.cz,
                    dimension: options.dimension,
                    worldType: options.worldType,
                    waterLevel: options.waterLevel,
                    seed: options.seed ?? this.currentSeed,
                    generateOnly: !!options.generateOnly,
                    voxels: options.voxels,
                    leftVoxels: options.leftVoxels,
                    rightVoxels: options.rightVoxels,
                    backVoxels: options.backVoxels,
                    frontVoxels: options.frontVoxels
                }); } catch (error) { this.failWorker(); }
            });
        }

        // Synchronous Main-Thread Rust Mesher
        meshChunk(chunk, neighbors, textureManager) {
            if (!this.ready) return null;
            if (this.materialList.length === 0) {
                this.syncMaterials(textureManager);
            }

            const memBuffer = this.wasmMemory.buffer;

            // 1. Copy current chunk voxels into Wasm
            const voxelsPtr = this.exports.eblan_get_chunk_voxels_ptr();
            new Uint8Array(memBuffer, voxelsPtr, 8192).set(chunk.voxels);

            // 2. Set neighbor chunk voxels
            const dirs = [
                { dir: 0, chunk: neighbors.right },
                { dir: 1, chunk: neighbors.left },
                { dir: 4, chunk: neighbors.front },
                { dir: 5, chunk: neighbors.back }
            ];

            for (let d of dirs) {
                if (d.chunk && d.chunk.voxels && d.chunk.isGenerated) {
                    const nPtr = this.exports.eblan_get_neighbor_voxels_ptr(d.dir);
                    new Uint8Array(memBuffer, nPtr, 8192).set(d.chunk.voxels);
                } else {
                    this.exports.eblan_set_neighbor_present(d.dir, 0);
                }
            }

            // 3. Execute Rust Greedy Meshing
            const vertexCount = this.exports.eblan_mesh_chunk(chunk.cx, chunk.cz);
            if (vertexCount === 0) return { positions: new Float32Array(0), normals: new Float32Array(0),
                uvs: new Float32Array(0), groups: [], materials: [] };

            // 4. Retrieve Zero-Copy packed buffers from Wasm
            const posPtr = this.exports.eblan_get_positions_ptr();
            const normPtr = this.exports.eblan_get_normals_ptr();
            const uvPtr = this.exports.eblan_get_uvs_ptr();
            const grpPtr = this.exports.eblan_get_groups_ptr();
            const grpCount = this.exports.eblan_get_group_count();

            const positions = new Float32Array(this.wasmMemory.buffer, posPtr, vertexCount * 3).slice();
            const normals = new Float32Array(this.wasmMemory.buffer, normPtr, vertexCount * 3).slice();
            const uvs = new Float32Array(this.wasmMemory.buffer, uvPtr, vertexCount * 2).slice();

            const rawGroups = new Uint32Array(this.wasmMemory.buffer, grpPtr, grpCount * 3);
            const groups = [];
            const materials = [];

            for (let g = 0; g < grpCount; g++) {
                const start = rawGroups[g * 3];
                const count = rawGroups[g * 3 + 1];
                const matId = rawGroups[g * 3 + 2];
                const mat = this.materialList[matId] || this.materialList[0];

                groups.push({
                    start: start,
                    count: count,
                    materialIndex: g
                });
                materials.push(mat);
            }

            return {
                positions: positions,
                normals: normals,
                uvs: uvs,
                groups: groups,
                materials: materials
            };
        }
    }

    window.EblanEng = new EblanEngine();
})(typeof window !== 'undefined' ? window : globalThis);
